      xml += '    <changefreq>monthly</changefreq>\n';
      xml += '    <priority>0.5</priority>\n';
      xml += `    <xhtml:link rel="alternate" hreflang="pt-BR" href="${siteUrl}/sobre-este-site" />\n`;
      xml += '  </url>\n';
