{
  "command": "entire trail",
  "short": "Manage trails across repositories and branches",
  "long": "A trail captures project intent across repositories and branches. Manage intent and discussions on the whole trail; use --repo and --branch to select context for checkout, sessions, findings, and approvals.",
  "guidance": "Trail commands talk to entire.io and read the saved login from the OS\nkeyring (the Keychain on macOS), so they need network and keyring access.\nIf you run commands in a sandbox, request unsandboxed execution for\n`entire trail` up front. An error saying the Keychain is not accessible or\nthe network is not allowed means the sandbox blocked it, not that the user\nis logged out: ask to re-run it unsandboxed, and do not run `entire login`.\n\nA project trail spans repositories; each change is its branch in one\nrepository. Project trails and changes are numbered separately: never\npass \u003cP\u003e where a change is expected, or \u003cn\u003e where a project trail is.\nPass \u003crepo\u003e/\u003cn\u003e to checkout, resume, finding, watch, approvals or\napprove; given to show, it shows the parent project trail.\nUsers paste Entire trail URLs. Do not pass a URL to any command; map\nthe path after the host to a selector:\n  \u003cforge\u003e/\u003cproject\u003e/-/trails/\u003cP\u003e/changes/\u003crepo\u003e/\u003cn\u003e  change \u003crepo\u003e/\u003cn\u003e\n  \u003cforge\u003e/\u003cproject\u003e/\u003crepo\u003e/-/trails/\u003cP\u003e/changes/\u003cn\u003e  change \u003crepo\u003e/\u003cn\u003e\n  \u003cforge\u003e/\u003cproject\u003e/\u003crepo\u003e/trails/\u003cn\u003e                change \u003crepo\u003e/\u003cn\u003e\n  \u003cforge\u003e/\u003cproject\u003e/-/trails/\u003cP\u003e                     project trail \u003cP\u003e\nAdd --project \u003cforge\u003e/\u003cproject\u003e unless \u003cproject\u003e is origin's owner.\nTo link a trail or change, use the url `entire trail show` prints.",
  "flags": [
    {
      "name": "project",
      "type": "string",
      "usage": "Project as gh/\u003cowner\u003e or et/\u003cproject\u003e; required for list, otherwise defaults to the repository's namespace"
    },
    {
      "name": "repo",
      "type": "string",
      "usage": "Target repository as forge/owner/repo (e.g. gh/acme/app) or a clone URL; for list, only filters the required --project"
    },
    {
      "name": "context",
      "type": "string",
      "usage": "Act as this saved login `name` for this command only — including the git and agent processes it spawns — instead of the active context (entire auth contexts lists them)"
    }
  ],
  "subcommands": [
    {
      "name": "approvals",
      "short": "List approval decisions on a trail",
      "audience": "read-only"
    },
    {
      "name": "approve",
      "short": "Approve a trail",
      "audience": "task-driven"
    },
    {
      "name": "checkout",
      "short": "Check out a trail's branch",
      "audience": "task-driven"
    },
    {
      "name": "comment",
      "short": "Discuss the whole trail across repositories",
      "audience": "task-driven"
    },
    {
      "name": "create",
      "short": "Create a trail and publish its branch",
      "audience": "task-driven"
    },
    {
