import { createAstronomyEngineTransitProvider } from './_shared/astronomyTransitProvider';
import { readBoundedJsonObject } from './_shared/boundedRequestBody';
import type { DadosPosicionaisV2 } from './_shared/positionV2';
import { validateDadosPosicionaisV2 } from './_shared/positionV2Schema';
import { recordTransitProvider } from './_shared/recordedTransitProvider';
import {
  type D1DatabaseLike,
  enforceRateLimit,
  getCorsHeaders,
  hasDisallowedOrigin,
  jsonResponse,
  requestBodyErrorResponse,
  securityHeaders,
} from './_shared/requestSecurity';
import { calculateTransitRunV1 } from './_shared/transitRunV1';
import { validateTransitRunV1 } from './_shared/transitRunV1Schema';

interface EnvBindings {
  BIGDATA_DB: D1DatabaseLike;
}

interface Context {
  request: Request;
  env: EnvBindings;
}

const MAP_ID_PATTERN = /^[A-Za-z0-9._:-]{8,128}$/;
const LOCAL_MAP_BODY_LIMIT_BYTES = 512 * 1024;

export async function onRequestOptions(context: Context) {
  return new Response(null, {
    headers: { ...getCorsHeaders(context.request, 'https://oraculo-celestial.app'), ...securityHeaders },
  });
}

export async function onRequestPost({ request, env }: Context) {
  const corsHeaders = getCorsHeaders(request, 'https://oraculo-celestial.app');
  if (hasDisallowedOrigin(request))
    return jsonResponse({ success: false, error: 'Origem não permitida.' }, 403, corsHeaders);

  const rateLimitError = await enforceRateLimit(env.BIGDATA_DB, request, 'astrologo/transitos');
  if (rateLimitError) {
    return new Response(rateLimitError.body, {
      status: rateLimitError.status,
      headers: { ...Object.fromEntries(rateLimitError.headers.entries()), ...corsHeaders },
    });
  }

  try {
    const payload = await readBoundedJsonObject(request, LOCAL_MAP_BODY_LIMIT_BYTES);
    const mapaId = typeof payload.mapaId === 'string' ? payload.mapaId.trim() : '';
    const horizonDays = payload.horizonDays === undefined ? 7 : Number(payload.horizonDays);
    if (!MAP_ID_PATTERN.test(mapaId)) {
      return jsonResponse(
        { success: false, error: 'Não foi possível reconhecer este mapa. Abra-o novamente.' },
        400,
        corsHeaders,
      );
    }
    if (!Number.isInteger(horizonDays) || horizonDays < 0 || horizonDays > 30) {
      return jsonResponse({ success: false, error: 'O horizonte deve ficar entre 0 e 30 dias.' }, 400, corsHeaders);
    }

    if (typeof payload.natal !== 'object' || payload.natal === null || Array.isArray(payload.natal)) {
      return jsonResponse(
        { success: false, error: 'O mapa natal local não foi enviado. Abra-o novamente.' },
        400,
        corsHeaders,
      );
    }
    const natal = payload.natal as unknown as DadosPosicionaisV2;
    const natalValidation = validateDadosPosicionaisV2(natal);
    if (!natalValidation.valid || natal.calculationId !== mapaId) {
      return jsonResponse(
        { success: false, error: 'Não foi possível usar o mapa natal. Faça um novo cálculo.' },
        409,
        corsHeaders,
      );
    }

    const referenceInstantUtc = new Date().toISOString();
    const natalSourceSha256 = await sha256Hex(JSON.stringify(natal));
    const { provider, observations } = recordTransitProvider(createAstronomyEngineTransitProvider());
    const transitRunV1 = calculateTransitRunV1({
      natal,
      natalSourceRef: `local://astrologo/mapSnapshots/${encodeURIComponent(mapaId)}`,
      natalSourceSha256,
      referenceInstantUtc,
      horizonDays,
      provider,
    });
    const validation = validateTransitRunV1(transitRunV1);
    if (!validation.valid) {
      console.error('Contrato TransitRunV1 inválido.', validation.errors);
      return jsonResponse(
        {
          success: false,
          code: 'TRANSIT_SCHEMA_VALIDATION_FAILED',
          error: 'Não foi possível concluir o céu atual. Tente novamente.',
        },
        500,
        corsHeaders,
      );
    }

    const runId = crypto.randomUUID();

    return jsonResponse({ success: true, runId, transitRunV1, transitObservations: observations }, 200, corsHeaders);
  } catch (error) {
    const bodyError = requestBodyErrorResponse(error, corsHeaders);
    if (bodyError) return bodyError;
    console.error('Falha ao calcular o céu atual.', {
      name: error instanceof Error ? error.name : 'UnknownError',
    });
