const RATE_LIMIT_CLEANUP_BATCH = 100;

export const jsonResponse = (body: unknown, status = 200, extraHeaders: Record<string, string> = {}) =>
  new Response(JSON.stringify(body), {
    status,
    headers: {
      'Content-Type': 'application/json',
      ...securityHeaders,
      ...extraHeaders,
    },
  });

export const requestBodyErrorResponse = (
  error: unknown,
  extraHeaders: Record<string, string> = {},
): Response | null => {
  if (error instanceof RequestBodyTooLargeError) {
    return jsonResponse({ success: false, error: 'A solicitação excede o limite permitido.' }, 413, extraHeaders);
  }
  if (error instanceof InvalidRequestBodyError) {
    return jsonResponse({ success: false, error: error.message }, error.httpStatus, extraHeaders);
  }
  return null;
};

export const isAllowedLcvOrigin = (origin: string): boolean =>
