export const getCorsHeaders = (
  request: Request,
  fallbackOrigin: string,
  methods = 'POST, OPTIONS',
): Record<string, string> => {
  const origin = request.headers.get('Origin') || '';
  const allowOrigin = isAllowedLcvOrigin(origin) ? origin : fallbackOrigin;

  return {
