import { type Env, handleGoogleStsMtls, type MtlsFetcher } from './index';

const STS_URL = 'https://sts.mtls.googleapis.com/v1/token';

const makeEnv = () => {
  let forwardedRequest: Request | undefined;
  const fetch = vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => {
    forwardedRequest = new Request(input, init);
    return new Response('{"access_token":"short-lived"}', {
      status: 200,
      headers: { 'Content-Type': 'application/json' },
    });
  });
  const env: Env = {
    GOOGLE_STS_UPSTREAM_MTLS: { fetch } satisfies MtlsFetcher,
  };
  return { env, fetch, forwardedRequest: () => forwardedRequest };
};

describe('Google STS mTLS transport Worker', () => {
  it('forwards the exact token exchange request through the native mTLS binding', async () => {
    const { env, fetch, forwardedRequest } = makeEnv();
    const body = JSON.stringify({ grant_type: 'urn:ietf:params:oauth:grant-type:token-exchange' });
    const response = await handleGoogleStsMtls(
      new Request(STS_URL, {
        method: 'POST',
        headers: {
          Authorization: 'must-not-cross-the-boundary',
          'Content-Type': 'application/json',
          'X-Untrusted': 'must-not-cross-the-boundary',
        },
        body,
      }),
      env,
    );

    expect(response.status).toBe(200);
    expect(fetch).toHaveBeenCalledOnce();
    expect(forwardedRequest()?.url).toBe(STS_URL);
    expect(forwardedRequest()?.method).toBe('POST');
    expect(forwardedRequest()?.headers.get('Content-Type')).toBe('application/json');
    expect([...(forwardedRequest()?.headers.keys() ?? [])]).toEqual(['content-type']);
    expect(forwardedRequest()?.redirect).toBe('manual');
    expect(await forwardedRequest()?.text()).toBe(body);
  });

  it('rejects an upstream redirect instead of following it outside the pinned STS origin', async () => {
    const fetch = vi.fn(
      async () =>
        new Response(null, {
          status: 302,
          headers: { Location: 'https://example.com/untrusted' },
        }),
    );
    const env: Env = { GOOGLE_STS_UPSTREAM_MTLS: { fetch } };

    const response = await handleGoogleStsMtls(
      new Request(STS_URL, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' }),
      env,
    );

    expect(response.status).toBe(502);
    expect(response.headers.get('Location')).toBeNull();
    expect(await response.text()).toBe('Google STS redirect rejected.');
  });

  it('rejects methods other than POST without touching the certificate binding', async () => {
    const { env, fetch } = makeEnv();
