import { fetchWithTimeout } from './_shared/externalFetch';
import {
  type D1DatabaseLike,
  enforceRateLimit,
  getCorsHeaders,
  hasDisallowedOrigin,
  jsonResponse,
  requestBodyErrorResponse,
  securityHeaders,
} from './_shared/requestSecurity';

interface EnvBindings {
  RESEND_API_KEY: string;
  BIGDATA_DB: D1DatabaseLike;
}

interface Context {
  request: Request;
  env: EnvBindings;
