const escapeHtml = (value: string): string =>
  value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');

const hasControlCharacter = (value: string): boolean =>
  Array.from(value).some((character) => {
    const code = character.charCodeAt(0);
    return code < 0x20 || code === 0x7f;
  });

function getCorsResponse(request: Request, data: unknown, status = 200) {
  const corsHeaders = getCorsHeaders(request, 'https://oraculo-celestial.app');
  return jsonResponse(data, status, corsHeaders);
}

export async function onRequestOptions(context: Context) {
  return new Response(null, {
    headers: { ...getCorsHeaders(context.request, 'https://oraculo-celestial.app'), ...securityHeaders },
  });
}

export async function onRequestPost(context: Context) {
  const { request, env } = context;

  if (hasDisallowedOrigin(request)) {
    return getCorsResponse(request, { ok: false, error: 'Origem não permitida.' }, 403);
  }
  const rateLimitError = await enforceRateLimit(env.BIGDATA_DB, request, 'astrologo/contato');
  if (rateLimitError) {
    return new Response(rateLimitError.body, {
      status: rateLimitError.status,
      headers: {
        ...Object.fromEntries(rateLimitError.headers.entries()),
        ...getCorsHeaders(request, 'https://oraculo-celestial.app'),
      },
    });
  }

  const envRec = env as unknown as Record<string, unknown>;
  const apiKey = REDACTED ||
    envRec.RESEND_APP_KEY ||
    envRec.RESEND_APPKEY ||
    envRec['resend-api-key'] ||
    envRec['resend-appkey']) as string;
  if (!apiKey) {
    console.error('Serviço de contato sem credencial de e-mail configurada.');
    return getCorsResponse(
      request,
      { ok: false, error: 'O envio de mensagens está temporariamente indisponível.' },
      503,
    );
  }

  try {
    const body = await readBoundedJsonObject(request, 8_192);
    if (
      typeof body.name !== 'string' ||
      (body.phone !== undefined && typeof body.phone !== 'string') ||
      typeof body.email !== 'string' ||
      typeof body.message !== 'string'
    ) {
      return getCorsResponse(request, { ok: false, error: 'Nome, e-mail e mensagem são obrigatórios.' }, 400);
    }
    const name = body.name.trim();
    const phone = body.phone?.trim() ?? '';
    const email = body.email.trim();
    const message = body.message.trim();
    const safeName = escapeHtml(name);
    const safePhone = escapeHtml(phone);
    const safeEmail = escapeHtml(email);
    const safeMessage = escapeHtml(message).replace(/\n/g, '<br>');

    if (
      !name ||
      name.length > 120 ||
      phone.length > 32 ||
      email.length > 254 ||
      !message ||
      message.length > 500 ||
      hasControlCharacter(name)
    ) {
      return getCorsResponse(request, { ok: false, error: 'Nome, e-mail e mensagem são obrigatórios.' }, 400);
    }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      return getCorsResponse(request, { ok: false, error: 'E-mail inválido.' }, 400);
    }

    const res = await fetchWithTimeout('https://api.resend.com/emails', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${apiKey}`,
      },
      body: JSON.stringify({
        from: 'Oráculo Astrológico <astrologo-app@lcv.app.br>',
        to: ['astrologo-app@lcv.app.br'],
        reply_to: email,
        subject: `📬 Contato — ${name}`,
        html: `
          <div style="font-family: 'Inter', system-ui, sans-serif; max-width: 600px; margin: 0 auto; padding: 32px;">
            <h2 style="color: #0d0d0d; margin: 0 0 24px;">Nova mensagem de contato</h2>
            <table style="width: 100%; border-collapse: collapse; margin-bottom: 24px;">
              <tr><td style="padding: 8px 0; color: #888; width: 100px;">Nome</td><td style="padding: 8px 0; font-weight: 700;">${safeName}</td></tr>
              <tr><td style="padding: 8px 0; color: #888;">E-mail</td><td style="padding: 8px 0;"><a href="mailto:${safeEmail}" style="color: #1a73e8;">${safeEmail}</a></td></tr>
              ${phone ? `<tr><td style="padding: 8px 0; color: #888;">Telefone</td><td style="padding: 8px 0;">${safePhone}</td></tr>` : ''}
            </table>
            <div style="background: #f5f4f4; border-radius: 12px; padding: 20px; color: #0d0d0d; line-height: 1.6;">
              ${safeMessage}
            </div>
          </div>
        `,
      }),
    });

    if (res.ok) {
      return getCorsResponse(request, { ok: true, message: 'Mensagem enviada com sucesso!' });
    }
    const data = (await res.json()) as Record<string, unknown>;
    console.error('O serviço de e-mail recusou a mensagem de contato.', { status: res.status, detail: data.message });
    return getCorsResponse(
      request,
      { ok: false, error: 'Não foi possível enviar a mensagem agora. Tente novamente.' },
      502,
    );
  } catch (error) {
    const bodyError = requestBodyErrorResponse(error, getCorsHeaders(request, 'https://oraculo-celestial.app'));
    if (bodyError) return bodyError;
    console.error('Falha inesperada no envio da mensagem de contato.', {
      name: error instanceof Error ? error.name : 'UnknownError',
    });
    return getCorsResponse(
      request,
      { ok: false, error: 'Não foi possível enviar a mensagem agora. Tente novamente.' },
      500,
    );
  }
}

const GOOGLE_STS_TOKEN_URL = 'https://sts.mtls.googleapis.com/v1/token';
const MAX_STS_REQUEST_BYTES = 32 * 1024;
const STS_TIMEOUT_MS = 10_000;

export interface MtlsFetcher {
  fetch(input: RequestInfo | URL, init?: RequestInit): Promise<Response>;
}

export interface Env {
  GOOGLE_STS_UPSTREAM_MTLS: MtlsFetcher;
}

const readBoundedBody = async (request: Request): Promise<Uint8Array<ArrayBuffer> | null> => {
  const contentLength = request.headers.get('Content-Length');
  if (contentLength && (!/^\d{1,10}$/u.test(contentLength) || Number(contentLength) > MAX_STS_REQUEST_BYTES)) {
    return null;
  }
  if (!request.body) return new Uint8Array();

  const reader = request.body.getReader();
  const chunks: Uint8Array[] = [];
  let byteLength = 0;
  try {
    while (true) {
      const chunk = await reader.read();
      if (chunk.done) break;
      byteLength += chunk.value.byteLength;
      if (byteLength > MAX_STS_REQUEST_BYTES) {
        await reader.cancel('body-limit');
        return null;
      }
      chunks.push(chunk.value);
    }
  } finally {
    reader.releaseLock();
  }

  const body = new Uint8Array(byteLength);
  let offset = 0;
  for (const chunk of chunks) {
    body.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return body;
};

export const handleGoogleStsMtls = async (request: Request, env: Env): Promise<Response> => {
  if (request.url !== GOOGLE_STS_TOKEN_URL) {
    return new Response(null, { status: 404 });
  }

  if (request.method !== 'POST') {
    return new Response(null, {
      status: 405,
      headers: { Allow: 'POST' },
    });
  }

  if (request.headers.get('Content-Type')?.split(';', 1)[0]?.trim().toLowerCase() !== 'application/json') {
    return new Response(null, { status: 415 });
  }

  const body = await readBoundedBody(request);
  if (!body) return new Response(null, { status: 413 });
  const response = await env.GOOGLE_STS_UPSTREAM_MTLS.fetch(GOOGLE_STS_TOKEN_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: body.buffer,
    redirect: 'manual',
    signal: AbortSignal.timeout(STS_TIMEOUT_MS),
  });
  if (response.status >= 300 && response.status < 400) {
    return new Response('Google STS redirect rejected.', { status: 502 });
  }
  return response;
};

export default {
  fetch: handleGoogleStsMtls,
};

import { describe, expect, it, vi } from 'vitest';

import { type Env, handleGoogleStsMtls, type MtlsFetcher } from './index';

const STS_URL = 'https://sts.mtls.googleapis.com/v1/token';

const makeEnv = () => {
  let forwardedRequest: Request | undefined;
  const fetch = vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => {
    forwardedRequest = new Request(input, init);
    return new Response('{"access_token":"short-lived"}', {
      status: 200,
      headers: { 'Content-Type': 'application/json' },
    });
  });
  const env: Env = {
    GOOGLE_STS_UPSTREAM_MTLS: { fetch } satisfies MtlsFetcher,
  };
  return { env, fetch, forwardedRequest: () => forwardedRequest };
};

describe('Google STS mTLS transport Worker', () => {
  it('forwards the exact token exchange request through the native mTLS binding', async () => {
    const { env, fetch, forwardedRequest } = makeEnv();
    const body = JSON.stringify({ grant_type: 'urn:ietf:params:oauth:grant-type:token-exchange' });
    const response = await handleGoogleStsMtls(
      new Request(STS_URL, {
        method: 'POST',
        headers: {
          Authorization: 'must-not-cross-the-boundary',
          'Content-Type': 'application/json',
          'X-Untrusted': 'must-not-cross-the-boundary',
        },
        body,
      }),
      env,
    );

    expect(response.status).toBe(200);
    expect(fetch).toHaveBeenCalledOnce();
    expect(forwardedRequest()?.url).toBe(STS_URL);
    expect(forwardedRequest()?.method).toBe('POST');
    expect(forwardedRequest()?.headers.get('Content-Type')).toBe('application/json');
    expect([...(forwardedRequest()?.headers.keys() ?? [])]).toEqual(['content-type']);
    expect(forwardedRequest()?.redirect).toBe('manual');
    expect(await forwardedRequest()?.text()).toBe(body);
  });

  it('rejects an upstream redirect instead of following it outside the pinned STS origin', async () => {
    const fetch = vi.fn(
      async () =>
        new Response(null, {
          status: 302,
          headers: { Location: 'https://example.com/untrusted' },
        }),
    );
    const env: Env = { GOOGLE_STS_UPSTREAM_MTLS: { fetch } };

    const response = await handleGoogleStsMtls(
      new Request(STS_URL, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' }),
      env,
    );

    expect(response.status).toBe(502);
    expect(response.headers.get('Location')).toBeNull();
    expect(await response.text()).toBe('Google STS redirect rejected.');
  });

  it('rejects methods other than POST without touching the certificate binding', async () => {
    const { env, fetch } = makeEnv();
    const response = await handleGoogleStsMtls(new Request(STS_URL), env);

    expect(response.status).toBe(405);
    expect(response.headers.get('Allow')).toBe('POST');
    expect(fetch).not.toHaveBeenCalled();
  });

  it('rejects every destination other than the exact Google STS token URL', async () => {
    const { env, fetch } = makeEnv();
    const response = await handleGoogleStsMtls(
      new Request('https://sts.mtls.googleapis.com/v1/token?unexpected=true', { method: 'POST' }),
      env,
    );

    expect(response.status).toBe(404);
    expect(fetch).not.toHaveBeenCalled();
  });

  it('rejects an oversized or non-JSON token exchange before using the certificate binding', async () => {
    const { env, fetch } = makeEnv();
    const oversized = await handleGoogleStsMtls(
      new Request(STS_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: 'x'.repeat(32 * 1024 + 1),
      }),
      env,
    );
    const wrongType = await handleGoogleStsMtls(
      new Request(STS_URL, { method: 'POST', headers: { 'Content-Type': 'text/plain' }, body: '{}' }),
      env,
    );

    expect(oversized.status).toBe(413);
    expect(wrongType.status).toBe(415);
    expect(fetch).not.toHaveBeenCalled();
  });
});

