import { InvalidRequestBodyError, RequestBodyTooLargeError } from './boundedRequestBody';

export const ASTROLOGO_PUBLIC_APP_ORIGIN = 'https://oraculo-celestial.app';

export const securityHeaders = {
  'X-Content-Type-Options': 'nosniff',
  'X-Frame-Options': 'DENY',
  'Referrer-Policy': 'strict-origin-when-cross-origin',
  'Permissions-Policy': 'geolocation=(), microphone=(), camera=()',
  'Cross-Origin-Resource-Policy': 'same-site',
} as const;

export interface D1Statement<TFirst = unknown> {
  bind: (...args: unknown[]) => D1Statement<TFirst>;
  first: () => Promise<TFirst | null>;
  run: () => Promise<unknown>;
  all: () => Promise<{ results: TFirst[] }>;
}

export interface D1BatchResult<T = unknown> {
  readonly success?: boolean;
  readonly results?: T[];
  readonly error?: string;
}

export interface D1DatabaseLike {
  prepare: <TFirst = unknown>(query: string) => D1Statement<TFirst>;
  batch?: <T = unknown>(statements: D1Statement<T>[]) => Promise<D1BatchResult<T>[]>;
}

const DEFAULT_RATE_POLICIES = {
  'astrologo/calcular': { enabled: 1, max_requests: 10, window_minutes: 10 },
  'astrologo/analisar': { enabled: 1, max_requests: 6, window_minutes: 15 },
  'astrologo/analisar-etapa': { enabled: 1, max_requests: 240, window_minutes: 60 },
  'astrologo/enviar-email': { enabled: 1, max_requests: 4, window_minutes: 60 },
  'astrologo/contato': { enabled: 1, max_requests: 5, window_minutes: 30 },
  'astrologo/transitos': { enabled: 1, max_requests: 6, window_minutes: 15 },
  'astrologo/sinastria': { enabled: 1, max_requests: 4, window_minutes: 15 },
  'astrologo/localidade': { enabled: 1, max_requests: 4, window_minutes: 30 },
} as const;

const RATE_LIMIT_RETENTION_MS = 24 * 60 * 60 * 1_000;
const RATE_LIMIT_CLEANUP_BATCH = 100;

export const jsonResponse = (body: unknown, status = 200, extraHeaders: Record<string, string> = {}) =>
  new Response(JSON.stringify(body), {
    .first();

  return {
    enabled: Number.parseInt(String(row?.enabled ?? fallback.enabled), 10) === 1,
    maxRequests: Math.max(1, Number.parseInt(String(row?.max_requests ?? fallback.max_requests), 10)),
    windowMinutes: Math.max(1, Number.parseInt(String(row?.window_minutes ?? fallback.window_minutes), 10)),
  };
}

export async function enforceRateLimit(
  db: D1DatabaseLike,
  request: Request,
  route: keyof typeof DEFAULT_RATE_POLICIES,
  options: { readonly subject?: string } = {},
) {
  const policy = await getRateLimitPolicy(db, route);
  if (!policy.enabled) return null;

  if (options.subject !== undefined && (options.subject.length === 0 || options.subject.length > 512)) {
    throw new TypeError('Invalid rate-limit subject.');
  }
  const bucketSize = policy.windowMinutes * 60 * 1000;
  const windowStart = Math.floor(Date.now() / bucketSize) * bucketSize;

  // Legacy unauthenticated routes remain partitioned by IP. Authenticated
  // routes may opt into a hashed subject so the raw Firebase UID is never
  // persisted. Both paths claim quota atomically to prevent concurrent
  // requests from overshooting the configured ceiling.
  const partition =
    options.subject === undefined ? getClientIp(request) : `subject:${await hashToken(options.subject)}`;
  const key = `${route}:${partition}:${windowStart}`;

  const claimed = await db
    .prepare<{ request_count?: number }>(`
    INSERT INTO astrologo_api_rate_limits (key, route, window_start, request_count, updated_at)
    VALUES (?, ?, ?, 1, CURRENT_TIMESTAMP)
    ON CONFLICT(key) DO UPDATE SET
      request_count = astrologo_api_rate_limits.request_count + 1,
      updated_at = CURRENT_TIMESTAMP
    WHERE astrologo_api_rate_limits.request_count < ?
    RETURNING request_count
  `)
    .bind(key, route, windowStart, policy.maxRequests)
    .first();

  // Bound storage growth without a table-wide blocking delete. The existing
  // (route, window_start) index keeps cleanup on the current route's bounded
  // range instead of scanning buckets for every route on every request.
  await db
    .prepare(
      `DELETE FROM astrologo_api_rate_limits
       WHERE key IN (
         SELECT key FROM astrologo_api_rate_limits
          WHERE route = ? AND window_start < ?
         ORDER BY window_start
         LIMIT ?
       )`,
    )
    .bind(route, Date.now() - RATE_LIMIT_RETENTION_MS, RATE_LIMIT_CLEANUP_BATCH)
    .run();

  if (!claimed) {
    return jsonResponse(
      { success: false, error: 'Muitas tentativas em pouco tempo. Tente novamente mais tarde.' },
      429,
      { 'Retry-After': String(policy.windowMinutes * 60) },
    );
  }

  return null;
}

