export interface D1TestStatement<TFirst = unknown> {
  bind: (...values: unknown[]) => D1TestStatement<TFirst>;
  first: () => Promise<TFirst | null>;
  run: () => Promise<unknown>;
  all: () => Promise<{ readonly results: TFirst[] }>;
}

export interface D1TestDatabase {
  prepare: <TFirst = unknown>(query: string) => D1TestStatement<TFirst>;
}

const EMPTY_META: D1Meta = {
  duration: 0,
  size_after: 0,
  rows_read: 0,
  rows_written: 0,
  last_row_id: 0,
  changed_db: false,
  changes: 0,
};

const unsupportedRaw = async (): Promise<never> => {
  throw new Error('This test does not exercise raw D1 rows.');
};

const toPreparedStatement = (statement: D1TestStatement): D1PreparedStatement => ({
  bind: (...values: unknown[]) => toPreparedStatement(statement.bind(...values)),
  first: async <T = Record<string, unknown>>(columnName?: string): Promise<T | null> => {
    if (columnName !== undefined) throw new Error('This test does not exercise scalar D1 reads.');
    const result = await statement.first();
    // D1 lets callers select T without a runtime decoder; this adapter contains that test-only boundary.
    return result as T | null;
  },
  run: async <T = Record<string, unknown>>(): Promise<D1Result<T>> => {
    await statement.run();
    return { success: true, meta: EMPTY_META, results: [] };
  },
  all: async <T = Record<string, unknown>>(): Promise<D1Result<T>> => {
    const result = await statement.all();
    return { success: true, meta: EMPTY_META, results: result.results as T[] };
  },
  raw: unsupportedRaw,
});

export const toD1Database = (database: D1TestDatabase): D1Database => ({
  prepare: (query: string) => toPreparedStatement(database.prepare(query)),
  batch: async <T = unknown>(statements: D1PreparedStatement[]): Promise<D1Result<T>[]> =>
    Promise.all(statements.map((statement) => statement.run<T>())),
  exec: async (): Promise<never> => {
    throw new Error('This test does not exercise D1 exec.');
  },
  withSession: (): never => {
    throw new Error('This test does not exercise D1 sessions.');
  },
  dump: async (): Promise<never> => {
    throw new Error('This test does not exercise D1 dump.');
  },
});

