const GOOGLE_STS_TOKEN_URL = 'https://sts.mtls.googleapis.com/v1/token';
const MAX_STS_REQUEST_BYTES = 32 * 1024;
const STS_TIMEOUT_MS = 10_000;

export type Env = Readonly<Pick<Cloudflare.Env, 'GOOGLE_STS_UPSTREAM_MTLS'>>;

const readBoundedBody = async (request: Request): Promise<Uint8Array<ArrayBuffer> | null> => {
  const contentLength = request.headers.get('Content-Length');
  if (contentLength && (!/^\d{1,10}$/u.test(contentLength) || Number(contentLength) > MAX_STS_REQUEST_BYTES)) {
    return null;
  }
  if (!request.body) return new Uint8Array();

  const reader = request.body.getReader();
  const chunks: Uint8Array[] = [];
  let byteLength = 0;
  try {
    while (true) {
      const chunk = await reader.read();
      if (chunk.done) break;
      byteLength += chunk.value.byteLength;
      if (byteLength > MAX_STS_REQUEST_BYTES) {
        await reader.cancel('body-limit');
        return null;
      }
      chunks.push(chunk.value);
    }
  } finally {
    reader.releaseLock();
  }

  const body = new Uint8Array(byteLength);
  let offset = 0;
  for (const chunk of chunks) {
    body.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return body;
};

export const handleGoogleStsMtls = async (request: Request, env: Env): Promise<Response> => {
  if (request.url !== GOOGLE_STS_TOKEN_URL) {
    return new Response(null, { status: 404 });
  }

  if (request.method !== 'POST') {
    return new Response(null, {
      status: 405,
      headers: { Allow: 'POST' },
    });
  }

  if (request.headers.get('Content-Type')?.split(';', 1)[0]?.trim().toLowerCase() !== 'application/json') {
    return new Response(null, { status: 415 });
  }

  const body = await readBoundedBody(request);
  if (!body) return new Response(null, { status: 413 });
  const response = await env.GOOGLE_STS_UPSTREAM_MTLS.fetch(GOOGLE_STS_TOKEN_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: body.buffer,
    redirect: 'manual',
    signal: AbortSignal.timeout(STS_TIMEOUT_MS),
  });
  if (response.status >= 300 && response.status < 400) {
    return new Response('Google STS redirect rejected.', { status: 502 });
  }
  return response;
};

